# -*- coding: utf-8 -*-
"""大雪地区広域連合 第9期計画の妥当性評価及び第10期施策の妥当性検証 報告書 生成スクリプト.

検証の材料は次のとおり。
  ・第9期介護保険事業計画（令和6年3月）本文
  ・東川町・美瑛町・東神楽町 高齢者福祉計画（第9期）
  ・第10期計画素案
  ・業務仕様書・起工伺
  ・地域包括ケア「見える化」システム出力（令和8年7月22日取得）
  ・令和7年度 健康とくらしの調査（JAGES調査）成果物
  ・北海道公表『第9期介護保険料（第1号被保険者分）各保険者の保険料等』（素案 表45経由）
数値はすべて上記の原典から取得したもので、推測値は用いていない。
出所が確認できない事項は「未確認」と明記している。
"""

from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter

FONT = "Carlito"
NAVY = "1F4E78"
PALE = "EAF3F8"
HEAD = "5B9BD5"
SUB = "404040"
IN_Y = "FFF2CC"   # 入力・未確定
OK_G = "E2EFDA"   # 妥当・達成
NG_O = "FCE4D6"   # 課題・未達
GRAY = "F2F2F2"

thin = Side(style="thin", color="BFBFBF")
BORDER = Border(left=thin, right=thin, top=thin, bottom=thin)

wb = Workbook()


def sheet(name, title, subtitle, widths):
    ws = wb.create_sheet(name)
    ws["A1"] = title
    ws["A1"].font = Font(name=FONT, size=15, bold=True, color="FFFFFF")
    ws["A1"].fill = PatternFill("solid", fgColor=NAVY)
    ws["A2"] = subtitle
    ws["A2"].font = Font(name=FONT, size=9)
    ws["A2"].fill = PatternFill("solid", fgColor=PALE)
    ws["A2"].alignment = Alignment(wrap_text=True, vertical="center")
    n = max(len(widths), 6)
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=n)
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=n)
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.row_dimensions[1].height = 26
    ws.row_dimensions[2].height = 30
    return ws


def heading(ws, row, text):
    c = ws.cell(row=row, column=1, value=text)
    c.font = Font(name=FONT, size=11, bold=True, color=NAVY)
    return row + 1


def table(ws, row, head, rows, fills=None, numfmt=None, rowheight=30, align=None):
    """fills: {行index(0起点): {列index(1起点): 色}}"""
    for i, h in enumerate(head, start=1):
        c = ws.cell(row=row, column=i, value=h)
        c.font = Font(name=FONT, size=9, bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor=SUB)
        c.alignment = Alignment(wrap_text=True, horizontal="center", vertical="center")
        c.border = BORDER
    ws.row_dimensions[row].height = 28
    r = row + 1
    for k, data in enumerate(rows):
        for i, v in enumerate(data, start=1):
            c = ws.cell(row=r, column=i, value=v)
            c.font = Font(name=FONT, size=9)
            ha = "left"
            if align and i in align:
                ha = align[i]
            elif isinstance(v, (int, float)):
                ha = "right"
            c.alignment = Alignment(wrap_text=True, horizontal=ha, vertical="top")
            c.border = BORDER
            if numfmt and isinstance(v, (int, float)):
                c.number_format = numfmt
            if fills and k in fills and i in fills[k]:
                c.fill = PatternFill("solid", fgColor=fills[k][i])
        ws.row_dimensions[r].height = rowheight
        r += 1
    return r - 1


def note(ws, row, text, ncol=10):
    c = ws.cell(row=row, column=1, value=text)
    c.font = Font(name=FONT, size=8, italic=True)
    c.alignment = Alignment(wrap_text=True, vertical="top")
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=ncol)
    ws.row_dimensions[row].height = 14 * max(1, len(text) // 110 + 1)
    return row + 1


