    ["9", "調査の妥当性", "第9期の5調査の対象数・回収率・標本規模から、結果の記述可能な範囲を評価する。", "記述に過大表現"],
    ["10", "第10期施策の妥当性", "計画素案の施策・KPIが、上記1〜9の検証結果に対応しているかを評価する。", "方向は妥当"],
